import{_ as e,C as a,c as o,o as i,j as s,b as t,a0 as r,a as l,w as n,G as u,a1 as d}from"./chunks/framework.DKRgXLPU.js";const c=JSON.parse('{"title":"Ser um ótimo jogador de equipe","description":"","frontmatter":{},"headers":[],"relativePath":"pt/education/team-player/index.md","filePath":"pt/education/team-player/index.md"}');const m=e({name:"pt/education/team-player/index.md"},[["render",function(e,c,m,p,h,q){const f=a("Mermaid");return i(),o("div",null,[c[1]||(c[1]=s("h1",{id:"ser-um-otimo-jogador-de-equipe",tabindex:"-1"},[l("Ser um ótimo jogador de equipe "),s("a",{class:"header-anchor",href:"#ser-um-otimo-jogador-de-equipe","aria-label":'Permalink to "Ser um ótimo jogador de equipe"'},"​")],-1)),c[2]||(c[2]=s("p",null,"A petanca é frequentemente jogada em equipes — duplas (doubletes) ou trios (tripletes). A habilidade individual é importante, mas a dinâmica da equipe pode determinar o sucesso ou o fracasso. As melhores equipes nem sempre são as mais habilidosas, mas sim aquelas que melhor trabalham juntas.",-1)),c[3]||(c[3]=s("div",{class:"tip custom-block"},[s("p",{class:"custom-block-title"},"A Grande Ideia"),s("p",null,[s("strong",null,"As melhores equipes nem sempre são as mais habilidosas, mas sim aquelas que trabalham melhor juntas."),l(" Ser humilde, ambicioso e emocionalmente inteligente faz de você um ótimo membro de equipe.")])],-1)),(i(),t(d,null,{default:n(()=>[u(f,{id:"mermaid-11",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5B%C3%93timo%20companheiro%20de%20equipe%5D%20--%3E%20B%5BHumilde%5D%0A%20%20%20%20A%20--%3E%20C%5BCom%20fome%5D%0A%20%20%20%20A%20--%3E%20D%5BInteligente%5D%0A%0A%20%20%20%20B%20--%3E%20E%5BSucesso%20da%20Equipe%5D%0A%20%20%20%20C%20--%3E%20E%0A%20%20%20%20D%20--%3E%20E%0A%0A%20%20%20%20E%20--%3E%20F%5BDesempenho%20de%20campe%C3%A3o%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e8f5e9%0A%20%20%20%20style%20B%20fill%3A%23e3f2fd%0A%20%20%20%20style%20C%20fill%3A%23fff4e1%0A%20%20%20%20style%20D%20fill%3A%23f3e5f5%0A%20%20%20%20style%20F%20fill%3A%23fff4e1%0A"})]),fallback:n(()=>[...c[0]||(c[0]=[l(" Loading... ",-1)])]),_:1})),c[4]||(c[4]=r('<h2 id="o-que-define-um-otimo-companheiro-de-equipe" tabindex="-1">O que define um ótimo companheiro de equipe? <a class="header-anchor" href="#o-que-define-um-otimo-companheiro-de-equipe" aria-label="Permalink to &quot;O que define um ótimo companheiro de equipe?&quot;">​</a></h2><p>Pesquisas e experiências apontam para três qualidades principais:</p><h3 id="_1-humilde" tabindex="-1">1. Humilde <a class="header-anchor" href="#_1-humilde" aria-label="Permalink to &quot;1. Humilde&quot;">​</a></h3><ul><li>Prioriza o sucesso da equipe em detrimento da glória pessoal.</li><li>Reconhece as contribuições dos outros.</li><li>Admite os erros sem dar desculpas.</li><li>Aberto a feedback e aprendizado</li><li>Não precisa ser a estrela.</li></ul><h3 id="_2-com-fome" tabindex="-1">2. Com fome <a class="header-anchor" href="#_2-com-fome" aria-label="Permalink to &quot;2. Com fome&quot;">​</a></h3><ul><li>Automotivado e determinado</li><li>Executa o trabalho sem que lhe peçam.</li><li>Sempre em busca de melhorias.</li><li>Traz energia para a equipe.</li><li>Não se apoia apenas no talento.</li></ul><h3 id="_3-inteligente-emocionalmente" tabindex="-1">3. Inteligente (emocionalmente) <a class="header-anchor" href="#_3-inteligente-emocionalmente" aria-label="Permalink to &quot;3. Inteligente (emocionalmente)&quot;">​</a></h3><ul><li>Sabe ler situações e pessoas.</li><li>Sabe quando falar e quando ouvir.</li><li>Gerencia suas próprias emoções</li><li>Apoia os colegas de equipe de forma adequada.</li><li>Lida com conflitos de forma construtiva.</li></ul><h2 id="os-fundamentos-do-sucesso-em-equipe" tabindex="-1">Os fundamentos do sucesso em equipe <a class="header-anchor" href="#os-fundamentos-do-sucesso-em-equipe" aria-label="Permalink to &quot;Os fundamentos do sucesso em equipe&quot;">​</a></h2><h3 id="objetivos-e-visao-compartilhados" tabindex="-1">Objetivos e visão compartilhados <a class="header-anchor" href="#objetivos-e-visao-compartilhados" aria-label="Permalink to &quot;Objetivos e visão compartilhados&quot;">​</a></h3><p>Equipes fortes possuem:</p><ul><li>Objetivos claros e acordados</li><li>Metas individuais alinhadas com as metas da equipe</li><li>Entendimento compartilhado sobre o que significa sucesso.</li><li>Compromisso com a missão coletiva</li></ul><p><strong>Perguntas para discutir com sua equipe:</strong></p><ul><li>O que estamos tentando alcançar juntos?</li><li>O que significa sucesso para nós?</li><li>De que forma nossos objetivos individuais contribuem para o sucesso da equipe?</li></ul><h3 id="comunicacao-eficaz" tabindex="-1">Comunicação eficaz <a class="header-anchor" href="#comunicacao-eficaz" aria-label="Permalink to &quot;Comunicação eficaz&quot;">​</a></h3><p>A comunicação é a essência do desempenho da equipe.</p><p><strong>Boa comunicação em equipe:</strong></p><ul><li>Aberto e honesto</li><li>Respeitoso, mesmo em discordância.</li><li>Claro e específico</li><li>Comunicação bidirecional (fala E escuta)</li><li>Oportuno (informação correta no momento certo)</li></ul><p><strong>Durante os jogos:</strong></p><ul><li>Discuta a estratégia antes de cada final.</li><li>Compartilhe observações sobre o terreno e os oponentes.</li><li>Coordenar quem arremessa e quando.</li><li>Apoiem-se mutuamente após os lançamentos (bons ou ruins).</li></ul><h3 id="confianca-e-respeito" tabindex="-1">Confiança e Respeito <a class="header-anchor" href="#confianca-e-respeito" aria-label="Permalink to &quot;Confiança e Respeito&quot;">​</a></h3><p>Sem confiança, as equipes se desfazem sob pressão.</p><p><strong>Construindo confiança:</strong></p><ul><li>Seja confiável (faça o que você diz)</li><li>Seja competente (faça bem o seu trabalho)</li><li>Seja honesto (mesmo quando for difícil)</li><li>Demonstre vulnerabilidade (admita as dificuldades)</li><li>Apoie os outros de forma consistente.</li></ul><p><strong>Demonstrando respeito:</strong></p><ul><li>Valorize a contribuição de cada pessoa.</li><li>Ouça diferentes perspectivas.</li><li>Reconheça o esforço, não apenas os resultados.</li><li>Trate o papel de cada um como importante.</li></ul><h3 id="funcoes-claras" tabindex="-1">Funções claras <a class="header-anchor" href="#funcoes-claras" aria-label="Permalink to &quot;Funções claras&quot;">​</a></h3><p>Todos devem entender:</p><ul><li>Suas principais responsabilidades</li><li>Como eles contribuem para a equipe</li><li>O que os outros esperam deles.</li><li>Quando avançar e quando recuar.</li></ul><p><strong>Em trios:</strong></p><table tabindex="0"><thead><tr><th>Papel</th><th>Foco principal</th><th>Qualidades Essenciais</th></tr></thead><tbody><tr><td>Ponteiro</td><td>Coloque as bolas perto do jack</td><td>Precisão, consistência</td></tr><tr><td>Meio</td><td>Adapte-se à situação.</td><td>Versatilidade, jogo de leitura</td></tr><tr><td>Atirador</td><td>Remova as bolas do oponente</td><td>Precisão sob pressão</td></tr></tbody></table><p>As funções podem ser flexíveis, mas a clareza ajuda.</p><h2 id="dinamica-de-equipe-durante-a-competicao" tabindex="-1">Dinâmica de equipe durante a competição <a class="header-anchor" href="#dinamica-de-equipe-durante-a-competicao" aria-label="Permalink to &quot;Dinâmica de equipe durante a competição&quot;">​</a></h2><h3 id="antes-do-jogo" tabindex="-1">Antes do jogo <a class="header-anchor" href="#antes-do-jogo" aria-label="Permalink to &quot;Antes do jogo&quot;">​</a></h3><ul><li>Chegar juntos, aquecer juntos</li><li>Discutir a estratégia geral</li><li>Defina o tom (positivo, focado)</li><li>Veja como todos estão se sentindo.</li></ul><h3 id="durante-o-jogo" tabindex="-1">Durante o jogo <a class="header-anchor" href="#durante-o-jogo" aria-label="Permalink to &quot;Durante o jogo&quot;">​</a></h3><ul><li>Comunicação entre as extremidades</li><li>Mantenha uma atitude positiva, independentemente do placar.</li><li>Apoiem-se mutuamente após erros.</li><li>Comemorem juntos as conquistas (brevemente)</li><li>Mantenha o foco no processo, não no resultado.</li></ul><h3 id="apos-erros" tabindex="-1">Após erros <a class="header-anchor" href="#apos-erros" aria-label="Permalink to &quot;Após erros&quot;">​</a></h3><p>O que NÃO fazer:</p><ul><li>Demonstre frustração visivelmente</li><li>Criticar ou culpar</li><li>Retirar-se ou ficar em silêncio</li><li>Reflita sobre o que aconteceu.</li></ul><p>O que fazer:</p><ul><li>Resposta rápida (&quot;sem problema&quot;)</li><li>Concentre-se no próximo arremesso.</li><li>Mantenha uma linguagem corporal positiva.</li><li>Confie que seu companheiro de equipe se recuperará.</li></ul><h3 id="apos-o-jogo" tabindex="-1">Após o jogo <a class="header-anchor" href="#apos-o-jogo" aria-label="Permalink to &quot;Após o jogo&quot;">​</a></h3><ul><li>Analisar juntos o resultado (o que funcionou, o que não funcionou).</li><li>Reconhecer as contribuições individuais</li><li>Discutir melhorias para a próxima vez.</li><li>Mantenha os relacionamentos independentemente do resultado.</li></ul><h2 id="padroes-de-comunicacao" tabindex="-1">Padrões de comunicação <a class="header-anchor" href="#padroes-de-comunicacao" aria-label="Permalink to &quot;Padrões de comunicação&quot;">​</a></h2><h3 id="feedback-construtivo" tabindex="-1">Feedback construtivo <a class="header-anchor" href="#feedback-construtivo" aria-label="Permalink to &quot;Feedback construtivo&quot;">​</a></h3><p><strong>Pobre:</strong> &quot;Você continua errando esses arremessos&quot; <strong>Melhor:</strong> &quot;Notei que os golpes estão indo para a esquerda - quer tentar ajustar sua postura?&quot;</p><h3 id="resposta-de-apoio-aos-erros" tabindex="-1">Resposta de apoio aos erros <a class="header-anchor" href="#resposta-de-apoio-aos-erros" aria-label="Permalink to &quot;Resposta de apoio aos erros&quot;">​</a></h3><p><strong>Ruim:</strong> <em>Silêncio ou frustração visível</em><strong>Melhor:</strong> &quot;Essa foi difícil. Você consegue lidar com a próxima.&quot;</p><h3 id="discussao-estrategica" tabindex="-1">Discussão estratégica <a class="header-anchor" href="#discussao-estrategica" aria-label="Permalink to &quot;Discussão estratégica&quot;">​</a></h3><p><strong>Pobre:</strong> &quot;Apenas atire&quot; <strong>Melhor:</strong> &quot;O que você acha: apontar para bloquear ou tentar chutar? Vejo prós e contras nas duas opções.&quot;</p><h2 id="construindo-uma-cultura-de-equipe" tabindex="-1">Construindo uma Cultura de Equipe <a class="header-anchor" href="#construindo-uma-cultura-de-equipe" aria-label="Permalink to &quot;Construindo uma Cultura de Equipe&quot;">​</a></h2><p>Grandes equipes desenvolvem habilidades compartilhadas:</p><ul><li><strong>Valores:</strong> Aquilo que defendemos</li><li><strong>Normas:</strong> Como nos comportamos</li><li><strong>Linguagem:</strong> Como nos comunicamos</li><li><strong>Rituais:</strong> O que fazemos juntos</li></ul><p><strong>Exemplos:</strong></p><ul><li>Aperte sempre as mãos antes e depois.</li><li>Frases específicas de incentivo</li><li>Rotina pré-jogo juntos</li><li>Refeição ou bebida pós-jogo</li></ul><h2 id="nesta-secao" tabindex="-1">Nesta seção <a class="header-anchor" href="#nesta-secao" aria-label="Permalink to &quot;Nesta seção&quot;">​</a></h2><ul><li><strong><a href="/en/education/team-player/communication">Comunicação em Equipe</a></strong> - Guia detalhado para se comunicar de forma eficaz</li></ul><h2 id="ponto-chave" tabindex="-1">Ponto-chave <a class="header-anchor" href="#ponto-chave" aria-label="Permalink to &quot;Ponto-chave&quot;">​</a></h2><blockquote><p>A força de uma equipe é medida pelo seu elo mais frágil, não pelo seu jogador mais fraco.</p></blockquote><p>Invista em seus companheiros de equipe. Construa confiança. Comunique-se bem. Vençam juntos.</p>',61))])}]]);export{c as __pageData,m as default};
